        FilesListing.__init__(self)
        CellsMapReader.__init__(self)
        SWPackage.__init__(self)
        FileGetter.__init__(self)
        SimpleFileGetter.__init__(self)
        BlackBox.__init__(self)
        QualityLevel.__init__(self)
        RawAlarmHistoryFileContentDeliverer.__init__(self)
        RawAlarmHistoryParser.__init__(self)
        ScfcParser.__init__(self)
        SiteconfParser.__init__(self)
        SysLog.__init__(self)
        MemDumps.__init__(self)
        FtpFileUploader.__init__(self)
